// insightsSyncCommand is the command that fills the resources these recipes
// read. It is `history`, not the generated `sync`: the generated sync cannot
// walk date windows, so it never writes these series.
const insightsSyncCommand = "garmin-pp-cli history"

// rollingWindowDays is the width of the rolling average both recipes report.
// Seven days is not a tuning knob: it is one whole week, so it cancels the
// weekday/weekend cycle that dominates both sleep and training data.
const rollingWindowDays = 7

// ---------------------------------------------------------------------------
// Archive access
// ---------------------------------------------------------------------------

// dayRow is one archived row of a day-keyed series. `day` is the row's own
// storage key, which for every series `history` walks by calendar day is the
// ISO date, so lexicographic order is chronological order.
type dayRow struct {
	day  string
	data json.RawMessage
}

// insightsWindow is the closed date range a recipe covers, plus the equally
// long window immediately before it that the trend compares against.
type insightsWindow struct {
	from      civilDay
	to        civilDay
	days      int
	priorFrom civilDay
	priorTo   civilDay
}

// resolveInsightsWindow turns the three window flags into one window.
//
// --days remains the default vocabulary (a rolling window ending today).
// --from/--to name an explicit range, which is what plan section 3 specifies
// and what a caller reproducing a past report needs. The two vocabularies do
// not mix: naming --days beside a complete --from/--to range would silently
// pick one, so it is refused.
func resolveInsightsWindow(end civilDay, days int, fromFlag, toFlag string, daysChanged bool) (insightsWindow, error) {
	fromFlag = strings.TrimSpace(fromFlag)
	toFlag = strings.TrimSpace(toFlag)
	if fromFlag == "" && toFlag == "" {
		if days < 1 {
			return insightsWindow{}, fmt.Errorf("--days must be at least 1, got %d", days)
		}
		return newInsightsWindow(end, days), nil
	}
	if fromFlag != "" && toFlag != "" && daysChanged {
		return insightsWindow{}, errors.New("--days cannot be combined with a complete --from/--to range; drop one")
	}
	if days < 1 {
		return insightsWindow{}, fmt.Errorf("--days must be at least 1, got %d", days)
	}
	var from, to civilDay
	var err error
	if toFlag != "" {
		if to, err = parseCivilDay(toFlag); err != nil {
			return insightsWindow{}, fmt.Errorf("--to: %w", err)
		}
	}
	if fromFlag != "" {
		if from, err = parseCivilDay(fromFlag); err != nil {
			return insightsWindow{}, fmt.Errorf("--from: %w", err)
		}
	}
	switch {
	case fromFlag != "" && toFlag != "":
		// both ends named
	case fromFlag != "":
		to = end
	default:
		from = to.addDays(-(days - 1))
	}
	if to.before(from) {
		return insightsWindow{}, fmt.Errorf("--from %s is after --to %s", from, to)
	}
	span := daysInclusive(from, to)
	return insightsWindow{
		from:      from,
		to:        to,
		days:      span,
		priorFrom: from.addDays(-span),
		priorTo:   from.addDays(-1),
	}, nil
}

func newInsightsWindow(end civilDay, days int) insightsWindow {
	if days < 1 {
		days = 1
	}
	from := end.addDays(-(days - 1))
	return insightsWindow{
		from:      from,
		to:        end,
		days:      days,
		priorFrom: from.addDays(-days),
		priorTo:   from.addDays(-1),
	}
}

func (w insightsWindow) period() map[string]any {
	return map[string]any{"from": w.from.String(), "to": w.to.String(), "days": w.days}
}

func (w insightsWindow) priorPeriod() map[string]any {
	return map[string]any{"from": w.priorFrom.String(), "to": w.priorTo.String(), "days": w.days}
}

// readDayRange returns every row of a day-keyed series whose storage key falls
// in [from, to]. The predicate is `resource_type = ? AND id BETWEEN ? AND ?`,
// which rides the resources table's (resource_type, id) primary key, so the
// cost is proportional to the days asked for rather than to the archive's
// size. A missing table is not an error: a home that has never been synced has
// no `resources` table at all, and that must read as an empty archive.
func readDayRange(db *store.Store, resourceType string, from, to civilDay) ([]dayRow, error) {
	const q = `SELECT id, data FROM resources
	           WHERE resource_type = ? AND id >= ? AND id <= ?
	           ORDER BY id`
	rows, err := db.DB().Query(q, resourceType, from.String(), to.String())
	if err != nil {
		if isMissingArchive(err) {
			return nil, nil
		}
		return nil, err
	}
	defer rows.Close() //nolint:errcheck // read-only query
	var out []dayRow
	for rows.Next() {
		var id string
		var raw []byte
		if err := rows.Scan(&id, &raw); err != nil {
			return nil, err
		}
		out = append(out, dayRow{day: id, data: append(json.RawMessage(nil), raw...)})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// readResource returns every row of a resource type. Used for series whose
// storage key is not a date — the activity feed is keyed by activity id, and
// per-activity heart-rate zones by their parent's id — so the date filter has
// to happen on a field inside the payload. The predicate still rides
// idx_resources_type rather than scanning the table.
func readResource(db *store.Store, resourceType string) ([]dayRow, error) {
	const q = `SELECT id, data FROM resources WHERE resource_type = ?`
	rows, err := db.DB().Query(q, resourceType)
	if err != nil {
		if isMissingArchive(err) {
			return nil, nil
		}
		return nil, err
	}
	defer rows.Close() //nolint:errcheck // read-only query
	var out []dayRow
	for rows.Next() {
		var id string
		var raw []byte
		if err := rows.Scan(&id, &raw); err != nil {
			return nil, err
		}
		out = append(out, dayRow{day: id, data: append(json.RawMessage(nil), raw...)})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// isMissingArchive reports whether an error means "this database has never
// been synced" rather than "this query is wrong". syncHintMissingTable is the
// generated detector; sql.ErrNoRows is folded in so a caller can use the same
// check on a single-row scan.
func isMissingArchive(err error) bool {
	return err != nil && (errors.Is(err, sql.ErrNoRows) || syncHintMissingTable(err))
}

// ---------------------------------------------------------------------------
// Small JSON readers
//
// Garmin leaves a field null rather than omitting it whenever a night or an
// activity was only partly measured, so every reader below distinguishes
// "absent or null" from "present and zero". A zero that came from a null would
// silently drag an average down.
// ---------------------------------------------------------------------------

func jsonNumberAt(raw json.RawMessage, path ...string) (float64, bool) {
	cur := raw
	for _, key := range path {
		child, ok := jsonChild(cur, key)
		if !ok {
			return 0, false
		}
		cur = child
	}
	var f float64
	if err := json.Unmarshal(cur, &f); err != nil {
		return 0, false
	}
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return 0, false
	}
	return f, true
}

func jsonStringAt(raw json.RawMessage, path ...string) (string, bool) {
	cur := raw
	for _, key := range path {
		child, ok := jsonChild(cur, key)
		if !ok {
			return "", false
		}
		cur = child
	}
	var s string
	if err := json.Unmarshal(cur, &s); err != nil {
		return "", false
	}
	return s, true
}

// ---------------------------------------------------------------------------
// Aggregation
// ---------------------------------------------------------------------------

// sampleSet accumulates one metric's observations. Nights or activities that
// carry no value for the metric are simply never added, so `n` is the honest
// denominator for that metric alone rather than the window's day count.
type sampleSet struct {
	values []float64
}

func (s *sampleSet) add(v float64) { s.values = append(s.values, v) }

func (s *sampleSet) n() int { return len(s.values) }

func (s *sampleSet) sum() float64 {
	total := 0.0
	for _, v := range s.values {
		total += v
	}
	return total
}

func (s *sampleSet) mean() *float64 {
	if len(s.values) == 0 {
		return nil
	}
	return round1(s.sum() / float64(len(s.values)))
}

func (s *sampleSet) median() *float64 {
	if len(s.values) == 0 {
		return nil
	}
	sorted := append([]float64(nil), s.values...)
	sort.Float64s(sorted)
	mid := len(sorted) / 2
	if len(sorted)%2 == 1 {
		return round1(sorted[mid])
	}
	return round1((sorted[mid-1] + sorted[mid]) / 2)
}

func (s *sampleSet) min() *float64 {
	if len(s.values) == 0 {
		return nil
	}
	m := s.values[0]
	for _, v := range s.values[1:] {
		if v < m {
			m = v
		}
	}
	return round1(m)
}

func (s *sampleSet) max() *float64 {
	if len(s.values) == 0 {
		return nil
	}
	m := s.values[0]
	for _, v := range s.values[1:] {
		if v > m {
			m = v
		}
	}
	return round1(m)
}

// summary is the same five-field block for every metric, so a consumer can
// parse one shape. Every field is a pointer: null means "not measured", which
// is different from zero.
func (s *sampleSet) summary() map[string]any {
	return map[string]any{
		"n":      s.n(),
		"avg":    s.mean(),
		"median": s.median(),
		"min":    s.min(),
		"max":    s.max(),
	}
}

func round1(v float64) *float64 {
	r := math.Round(v*10) / 10
	return &r
}

// deltaBlock compares this window's mean against the prior window's. A null
// delta means one of the two windows had no observations at all — the honest
// answer when an archive does not reach back far enough to compare.
func deltaBlock(current, prior *sampleSet) map[string]any {
	block := map[string]any{
		"current":     current.mean(),
		"current_n":   current.n(),
		"prior":       prior.mean(),
		"prior_n":     prior.n(),
		"delta":       nil,
		"delta_pct":   nil,
		"comparable":  false,
		"explanation": "the prior period has no measurements to compare against",
	}
	c, p := current.mean(), prior.mean()
	if c == nil || p == nil {
		if c == nil {
			block["explanation"] = "this period has no measurements"
		}
		return block
	}
	d := *c - *p
	block["delta"] = round1(d)
	if *p != 0 {
		block["delta_pct"] = round1(d / *p * 100)
	}
	block["comparable"] = true
	block["explanation"] = ""
	return block
}

// rollingPoint is one day of a trailing average.
type rollingPoint struct {
	Date  string   `json:"date"`
	N     int      `json:"n"`
	Value *float64 `json:"value"`
}

// rollingAverage walks the window day by day and averages the trailing
// `rollingWindowDays` days of whatever the caller measured. Days with no
// measurement lower `n` for that point rather than being treated as zero, so a
// reader can tell a genuinely low week from a week the watch was off the wrist.
func rollingAverage(byDay map[string]float64, w insightsWindow) []rollingPoint {
	points := make([]rollingPoint, 0, w.days)
	for d := w.from; !d.after(w.to); d = d.addDays(1) {
		set := &sampleSet{}
		for back := 0; back < rollingWindowDays; back++ {
			if v, ok := byDay[d.addDays(-back).String()]; ok {
				set.add(v)
			}
		}
		points = append(points, rollingPoint{Date: d.String(), N: set.n(), Value: set.mean()})
	}
	return points
}

