// Command
// ---------------------------------------------------------------------------

func newGarminInsightsCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "insights",
		Short:       "Multi-series recipes over the local Garmin archive",
		Annotations: map[string]string{"mcp:read-only": "true"},
		Long: `Answer questions that span several Garmin series at once, entirely from the
local archive. These recipes make no network call: run '` + insightsSyncCommand + `'
first to fill the archive, then read it as often as you like.

An archive with no rows is not an error. Every count comes back zero, every
average comes back null, and a hint on stderr names the command that would
populate it.`,
		Example: `  # Sleep duration, score, stage split and 7-day trend over four weeks
  garmin-pp-cli insights sleep --days 28

  # Training breakdown, heart-rate zone distribution and weekly load
  garmin-pp-cli insights training --days 28 --json`,
	}
	cmd.AddCommand(newGarminInsightsSleepCmd(flags))
	cmd.AddCommand(newGarminInsightsTrainingCmd(flags))
	return cmd
}

// insightsRunner carries what both recipes need: the opened archive, the
// window, and the warnings collected while reading.
type insightsRunner struct {
	db       *store.Store
	window   insightsWindow
	warnings []string
}

func (r *insightsRunner) warn(format string, args ...any) {
	r.warnings = append(r.warnings, fmt.Sprintf(format, args...))
}

func (r *insightsRunner) warningsOrEmpty() []string {
	if r.warnings == nil {
		return []string{}
	}
	return r.warnings
}

// withInsightsArchive opens the archive, builds the window, runs the recipe
// and prints its result. Everything a recipe shares — flag parsing, the empty
// archive hint, the output convention — lives here so the two recipes differ
// only in what they compute.
func withInsightsArchive(
	cmd *cobra.Command,
	flags *rootFlags,
	dbPath string,
	window insightsWindow,
	recipe string,
	compute func(*insightsRunner) (map[string]any, int),
) error {
	out := cmd.OutOrStdout()
	if dbPath == "" {
		dbPath = garminArchivePath(cmd.Context(), cmd.ErrOrStderr())
	}
	db, err := store.OpenWithContext(cmd.Context(), dbPath)
	if err != nil {
		return fmt.Errorf("opening local database: %w\nRun '%s' first.", err, insightsSyncCommand)
	}
	defer db.Close() //nolint:errcheck // read-only

	runner := &insightsRunner{db: db, window: window}
	result, rowsRead := compute(runner)
	result["recipe"] = recipe
	result["period"] = runner.window.period()
	result["prior_period"] = runner.window.priorPeriod()
	result["warnings"] = runner.warningsOrEmpty()
	result["rows_read"] = rowsRead

	if rowsRead == 0 {
		fmt.Fprintf(cmd.ErrOrStderr(),
			"hint: the local archive has no %s rows in %s..%s. Run '%s --since all' to fill it.\n",
			recipe, runner.window.from, runner.window.to, insightsSyncCommand)
	} else {
		hintIfStale(cmd, db, "", flags.maxAge)
	}

	if wantsMachineOutput(flags) {
		return printJSONFiltered(out, result, flags)
	}
	return printInsightsTable(out, recipe, result)
}

