// Recipe 1 — sleep
// ---------------------------------------------------------------------------

func newGarminInsightsSleepCmd(flags *rootFlags) *cobra.Command {
	var days int
	var dbPath string
	var fromDay, toDay string

	cmd := &cobra.Command{
		Use:         "sleep",
		Short:       "Nightly duration, score, stage split and 7-day trend",
		Annotations: map[string]string{"mcp:read-only": "true"},
		Long: `Summarise archived sleep over a window and compare it with the equally long
window before it.

Duration, stage minutes and score come from the sleep_stats series, whose
per-night row carries all three; the sleep_score series backs the score up when
a night has stats but no score. Stage minutes are reported both absolutely and
as a share of measured sleep, so a short night and a badly split one are
distinguishable.

Nights the watch did not measure are counted as missing, never as zero: every
average names the number of nights that fed it.`,
		Example: `  garmin-pp-cli insights sleep --days 28
  garmin-pp-cli insights sleep --from 2026-06-01 --to 2026-08-31
  garmin-pp-cli insights sleep --days 90 --json`,
		RunE: func(cmd *cobra.Command, args []string) error {
			window, err := resolveInsightsWindow(insightsToday(), days, fromDay, toDay, cmd.Flags().Changed("days"))
			if err != nil {
				return err
			}
			return withInsightsArchive(cmd, flags, dbPath, window, "sleep", computeSleepInsights)
		},
	}
	cmd.Flags().IntVar(&days, "days", 28, "Number of calendar days to summarise, ending today. Ignore it and pass --from/--to for an explicit range.")
	cmd.Flags().StringVar(&fromDay, "from", "", "First calendar day to summarise (YYYY-MM-DD). With --to, names an explicit range; alone, runs from that day through today.")
	cmd.Flags().StringVar(&toDay, "to", "", "Last calendar day to summarise (YYYY-MM-DD). Alone, ends a --days-long window on that day.")
	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path. The default is this home's data directory data.db, which is named for the home rather than for the credential in use, so a token refresh never orphans it; pass --db to read or write a different file.")
	return cmd
}

// sleepStageFields maps the output name of each sleep stage to the field the
// sleep_stats payload carries it in. Verified against a live 90-day archive on
// 2026-09-08: the four stage fields are seconds, and deep+light+rem equals
// totalSleepTimeInSeconds on all 87 measured nights.
var sleepStageFields = []struct {
	name  string
	field string
}{
	{"deep", "deepTime"},
	{"light", "lightTime"},
	{"rem", "remTime"},
	{"awake", "awakeTime"},
}

func computeSleepInsights(r *insightsRunner) (map[string]any, int) {
	current, curRows := r.readSleepWindow(r.window.from, r.window.to)
	prior, priorRows := r.readSleepWindow(r.window.priorFrom, r.window.priorTo)

	stages := map[string]any{}
	measuredTotal := 0.0
	for _, stage := range sleepStageFields {
		measuredTotal += current.stages[stage.name].sum()
	}
	for _, stage := range sleepStageFields {
		set := current.stages[stage.name]
		block := set.summary()
		if measuredTotal > 0 && set.n() > 0 {
			block["pct_of_measured"] = round1(set.sum() / measuredTotal * 100)
		} else {
			block["pct_of_measured"] = nil
		}
		stages[stage.name] = block
	}

	result := map[string]any{
		"coverage": map[string]any{
			"days_requested":       r.window.days,
			"nights_with_stats":    current.nightsWithStats,
			"nights_with_duration": current.duration.n(),
			"nights_with_score":    current.score.n(),
			"nights_with_stages":   current.stages["deep"].n(),
		},
		"duration_minutes": current.duration.summary(),
		"score":            current.score.summary(),
		"resting_hr":       current.restingHR.summary(),
		"stage_minutes":    stages,
		"rolling_7day": map[string]any{
			"duration_minutes": rollingAverage(current.durationByDay, r.window),
			"score":            rollingAverage(current.scoreByDay, r.window),
		},
		"trend_vs_prior_period": map[string]any{
			"duration_minutes": deltaBlock(current.duration, prior.duration),
			"score":            deltaBlock(current.score, prior.score),
			"deep_minutes":     deltaBlock(current.stages["deep"], prior.stages["deep"]),
			"rem_minutes":      deltaBlock(current.stages["rem"], prior.stages["rem"]),
		},
	}

	if curRows == 0 {
		r.warn("no sleep rows are archived for %s..%s", r.window.from, r.window.to)
	} else if current.nightsWithStats == 0 {
		// Scores without stats is a half-populated archive: the score block
		// stands on its own, but duration and every stage are null and would
		// otherwise read as "measured and empty" rather than "never walked".
		r.warn("the window has %d sleep scores but no sleep_stats rows, so duration and stage minutes are unavailable; run '%s' to fill them",
			current.score.n(), insightsSyncCommand)
	} else if missing := r.window.days - current.nightsWithStats; missing > 0 {
		r.warn("%d of %d nights in the window have no archived sleep row", missing, r.window.days)
	}
	if priorRows == 0 {
		r.warn("the prior period %s..%s has no archived sleep rows, so trends are not comparable",
			r.window.priorFrom, r.window.priorTo)
	}
	return result, curRows
}

// sleepAggregate is one window's worth of accumulated sleep observations.
type sleepAggregate struct {
	nightsWithStats int
	duration        *sampleSet
	score           *sampleSet
	restingHR       *sampleSet
	stages          map[string]*sampleSet
	durationByDay   map[string]float64
	scoreByDay      map[string]float64
}

func newSleepAggregate() *sleepAggregate {
	agg := &sleepAggregate{
		duration:      &sampleSet{},
		score:         &sampleSet{},
		restingHR:     &sampleSet{},
		stages:        map[string]*sampleSet{},
		durationByDay: map[string]float64{},
		scoreByDay:    map[string]float64{},
	}
	for _, stage := range sleepStageFields {
		agg.stages[stage.name] = &sampleSet{}
	}
	return agg
}

// readSleepWindow accumulates one window. It returns the aggregate and the
// number of archived rows it actually read, which is what decides whether the
// caller prints the empty-archive hint.
func (r *insightsRunner) readSleepWindow(from, to civilDay) (*sleepAggregate, int) {
	agg := newSleepAggregate()

	stats, err := readDayRange(r.db, "sleep_stats", from, to)
	if err != nil {
		r.warn("reading sleep_stats: %v", err)
		return agg, 0
	}
	scoresOnly := map[string]float64{}
	scores, err := readDayRange(r.db, "sleep_score", from, to)
	if err != nil {
		r.warn("reading sleep_score: %v", err)
	}
	for _, row := range scores {
		if v, ok := jsonNumberAt(row.data, "value"); ok {
			scoresOnly[row.day] = v
		}
	}

	for _, row := range stats {
		agg.nightsWithStats++
		if secs, ok := jsonNumberAt(row.data, "values", "totalSleepTimeInSeconds"); ok && secs > 0 {
			minutes := secs / 60
			agg.duration.add(minutes)
			agg.durationByDay[row.day] = minutes
		}
		score, ok := jsonNumberAt(row.data, "values", "sleepScore")
		if !ok {
			score, ok = scoresOnly[row.day]
		}
		if ok {
			agg.score.add(score)
			agg.scoreByDay[row.day] = score
		}
		if hr, ok := jsonNumberAt(row.data, "values", "restingHeartRate"); ok {
			agg.restingHR.add(hr)
		}
		for _, stage := range sleepStageFields {
			if secs, ok := jsonNumberAt(row.data, "values", stage.field); ok {
				agg.stages[stage.name].add(secs / 60)
			}
		}
	}

	// A night with a score but no stats row still counts toward the score.
	for day, v := range scoresOnly {
		if _, seen := agg.scoreByDay[day]; seen {
			continue
		}
		agg.score.add(v)
		agg.scoreByDay[day] = v
	}

	return agg, len(stats) + len(scores)
}

