func newGarminInsightsTrainingCmd(flags *rootFlags) *cobra.Command {
	var days int
	var dbPath string
	var fromDay, toDay string

	cmd := &cobra.Command{
		Use:         "training",
		Short:       "Activity breakdown, heart-rate zone split, weekly load and fitness trend",
		Annotations: map[string]string{"mcp:read-only": "true"},
		Long: `Summarise archived training over a window.

Activities are grouped by Garmin's own activity type key, and each group
reports its count, moving time and distance. Time in heart-rate zone is summed
across every activity that has zones archived — the count of those is reported
next to it, because an activity recorded without a heart-rate strap contributes
duration but no zone time.

Weekly load buckets activities by ISO week. VO2 max and training readiness are
reported as trends when the archive carries them; a series with no rows reports
zero days rather than an error.`,
		Example: `  garmin-pp-cli insights training --days 28
  garmin-pp-cli insights training --from 2026-06-01 --to 2026-08-31
  garmin-pp-cli insights training --days 90 --agent`,
		RunE: func(cmd *cobra.Command, args []string) error {
			window, err := resolveInsightsWindow(insightsToday(), days, fromDay, toDay, cmd.Flags().Changed("days"))
			if err != nil {
				return err
			}
			return withInsightsArchive(cmd, flags, dbPath, window, "training", computeTrainingInsights)
		},
	}
	cmd.Flags().IntVar(&days, "days", 28, "Number of calendar days to summarise, ending today. Ignore it and pass --from/--to for an explicit range.")
	cmd.Flags().StringVar(&fromDay, "from", "", "First calendar day to summarise (YYYY-MM-DD). With --to, names an explicit range; alone, runs from that day through today.")
	cmd.Flags().StringVar(&toDay, "to", "", "Last calendar day to summarise (YYYY-MM-DD). Alone, ends a --days-long window on that day.")
	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path. The default is this home's data directory data.db, which is named for the home rather than for the credential in use, so a token refresh never orphans it; pass --db to read or write a different file.")
	return cmd
}

type activityRecord struct {
	id       string
	day      civilDay
	typeKey  string
	duration float64 // seconds
	distance float64 // metres
	load     float64
	hasLoad  bool
	avgHR    float64
	hasAvgHR bool
}

// activityStartDay reads the local start date out of an activity payload.
// startTimeLocal is `YYYY-MM-DD HH:MM:SS`; the date half is taken verbatim
// rather than parsed into a time, because the archive's day boundaries are the
// account's local calendar days and re-deriving them through a zone would
// reintroduce exactly the drift civilDay exists to avoid.
func activityStartDay(raw json.RawMessage) (civilDay, bool) {
	s, ok := jsonStringAt(raw, "startTimeLocal")
	if !ok || len(s) < 10 {
		return civilDay{}, false
	}
	return dayFromValue(s[:10])
}

func computeTrainingInsights(r *insightsRunner) (map[string]any, int) {
	current := r.readActivities(r.window.from, r.window.to)
	prior := r.readActivities(r.window.priorFrom, r.window.priorTo)
	if len(current) == 0 {
		r.warn("no activities are archived for %s..%s", r.window.from, r.window.to)
	}

	// --- totals and per-type breakdown ---
	byType := map[string]*activityGroup{}
	totalDuration, totalDistance := &sampleSet{}, &sampleSet{}
	loadSet, priorLoadSet := &sampleSet{}, &sampleSet{}
	for _, act := range current {
		group, ok := byType[act.typeKey]
		if !ok {
			group = &activityGroup{typeKey: act.typeKey, hr: &sampleSet{}}
			byType[act.typeKey] = group
		}
		group.count++
		group.duration += act.duration
		group.distance += act.distance
		if act.hasAvgHR {
			group.hr.add(act.avgHR)
		}
		totalDuration.add(act.duration)
		totalDistance.add(act.distance)
		if act.hasLoad {
			loadSet.add(act.load)
		}
	}
	for _, act := range prior {
		if act.hasLoad {
			priorLoadSet.add(act.load)
		}
	}

	typeRows := make([]map[string]any, 0, len(byType))
	for _, group := range byType {
		typeRows = append(typeRows, group.row())
	}
	sort.Slice(typeRows, func(i, j int) bool {
		li, lj := typeRows[i]["duration_minutes"].(float64), typeRows[j]["duration_minutes"].(float64)
		if li != lj {
			return li > lj
		}
		return typeRows[i]["type"].(string) < typeRows[j]["type"].(string)
	})

	// --- heart-rate zone distribution ---
	zoneSeconds, activitiesWithZones := r.readHRZones(current)
	zoneTotal := 0.0
	for _, secs := range zoneSeconds {
		zoneTotal += secs
	}
	zoneNumbers := make([]int, 0, len(zoneSeconds))
	for zone := range zoneSeconds {
		zoneNumbers = append(zoneNumbers, zone)
	}
	sort.Ints(zoneNumbers)
	zoneRows := make([]map[string]any, 0, len(zoneNumbers))
	for _, zone := range zoneNumbers {
		row := map[string]any{
			"zone":    zone,
			"minutes": *round1(zoneSeconds[zone] / 60),
			"pct":     nil,
		}
		if zoneTotal > 0 {
			row["pct"] = round1(zoneSeconds[zone] / zoneTotal * 100)
		}
		zoneRows = append(zoneRows, row)
	}

	// --- weekly load ---
	weekly := r.weeklyLoad(current)

	result := map[string]any{
		"coverage": map[string]any{
			"days_requested":        r.window.days,
			"activities":            len(current),
			"activities_with_zones": activitiesWithZones,
			"activity_types":        len(byType),
		},
		"totals": map[string]any{
			"activities":       len(current),
			"duration_minutes": *round1(totalDuration.sum() / 60),
			"distance_km":      *round1(totalDistance.sum() / 1000),
			"training_load":    *round1(loadSet.sum()),
		},
		"by_type":           typeRows,
		"hr_zones":          zoneRows,
		"weekly":            weekly,
		"intensity_minutes": r.readIntensityMinutes(),
		"vo2max":            r.readVO2Max(),
		"readiness":         r.readReadiness(),
		"trend_vs_prior_period": map[string]any{
			"activities": map[string]any{
				"current": len(current),
				"prior":   len(prior),
				"delta":   len(current) - len(prior),
			},
			"training_load_per_activity": deltaBlock(loadSet, priorLoadSet),
		},
	}

	if len(current) > 0 && activitiesWithZones < len(current) {
		r.warn("%d of %d activities have no archived heart-rate zones, so zone minutes understate the window",
			len(current)-activitiesWithZones, len(current))
	}
	return result, len(current)
}

type activityGroup struct {
	typeKey  string
	count    int
	duration float64
	distance float64
	hr       *sampleSet
}

func (g *activityGroup) row() map[string]any {
	name := g.typeKey
	if name == "" {
		name = "unknown"
	}
	return map[string]any{
		"type":             name,
		"count":            g.count,
		"duration_minutes": *round1(g.duration / 60),
		"distance_km":      *round1(g.distance / 1000),
		"avg_hr":           g.hr.mean(),
	}
}

func (r *insightsRunner) readActivities(from, to civilDay) []activityRecord {
	rows, err := readResource(r.db, "activities")
	if err != nil {
		r.warn("reading activities: %v", err)
		return nil
	}
	var out []activityRecord
	undated := 0
	for _, row := range rows {
		day, ok := activityStartDay(row.data)
		if !ok {
			undated++
			continue
		}
		if day.before(from) || day.after(to) {
			continue
		}
		rec := activityRecord{id: store.BareResourceID(row.day), day: day}
		if key, ok := jsonStringAt(row.data, "activityType", "typeKey"); ok {
			rec.typeKey = key
		}
		if v, ok := jsonNumberAt(row.data, "duration"); ok {
			rec.duration = v
		}
		if v, ok := jsonNumberAt(row.data, "distance"); ok {
			rec.distance = v
		}
		if v, ok := jsonNumberAt(row.data, "activityTrainingLoad"); ok {
			rec.load, rec.hasLoad = v, true
		}
		if v, ok := jsonNumberAt(row.data, "averageHR"); ok {
			rec.avgHR, rec.hasAvgHR = v, true
		}
		out = append(out, rec)
	}
	if undated > 0 {
		r.warn("%d archived activities carry no startTimeLocal and were left out of the window", undated)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].day.String() < out[j].day.String() })
	return out
}

// readHRZones sums seconds per zone across the given activities and returns
// how many of them actually carry zone entries. The activity_hr_zones series
// is keyed by activity id, so only the activities in the window contribute —
// the archive holds zones for older activities too.
func (r *insightsRunner) readHRZones(activities []activityRecord) (map[int]float64, int) {
	wanted := make(map[string]struct{}, len(activities))
	for _, act := range activities {
		wanted[act.id] = struct{}{}
	}
	rows, err := readResource(r.db, "activity_hr_zones")
	if err != nil {
		r.warn("reading activity_hr_zones: %v", err)
		return map[int]float64{}, 0
	}
	seconds := map[int]float64{}
	matched := 0
	for _, row := range rows {
		if _, ok := wanted[store.BareResourceID(row.day)]; !ok {
			continue
		}
		zones, ok := jsonChild(row.data, "hrTimeInZones")
		if !ok {
			continue
		}
		var items []json.RawMessage
		if err := json.Unmarshal(zones, &items); err != nil {
			continue
		}
		// An archived row with an empty hrTimeInZones list is an activity
		// recorded without a heart-rate strap: Garmin answers [] and the
		// archive stores it faithfully, so the row exists and covers nothing.
		// Count the entries, not the row — they are also what feeds the sum
		// below, so the counter describes exactly what the zone minutes came
		// from. zoneCount agrees with the entry count on every archived row
		// measured (owner: 84 rows at 0/0; kavita: 3258 rows, 3173 at 5/5, 85 at 0/0), so the
		// entries are used rather than a second field that can disagree.
		if len(items) == 0 {
			continue
		}
		matched++
		for _, item := range items {
			number, hasNumber := jsonNumberAt(item, "zoneNumber")
			secs, hasSecs := jsonNumberAt(item, "secsInZone")
			if !hasNumber || !hasSecs {
				continue
			}
			seconds[int(number)] += secs
		}
	}
	return seconds, matched
}

// weeklyLoad buckets the window's activities into weeks that start on Monday.
func (r *insightsRunner) weeklyLoad(activities []activityRecord) []map[string]any {
	type bucket struct {
		count    int
		duration float64
		distance float64
		load     float64
	}
	buckets := map[string]*bucket{}
	for _, act := range activities {
		key := act.day.weekStart().String()
		b, ok := buckets[key]
		if !ok {
			b = &bucket{}
			buckets[key] = b
		}
		b.count++
		b.duration += act.duration
		b.distance += act.distance
		if act.hasLoad {
			b.load += act.load
		}
	}
	keys := make([]string, 0, len(buckets))
	for k := range buckets {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]map[string]any, 0, len(keys))
	for _, k := range keys {
		b := buckets[k]
		out = append(out, map[string]any{
			"week_start":       k,
			"activities":       b.count,
			"duration_minutes": *round1(b.duration / 60),
			"distance_km":      *round1(b.distance / 1000),
			"training_load":    *round1(b.load),
		})
	}
	return out
}

// readIntensityMinutes reads the weekly intensity-minute series. Garmin
// reports this one row per week, so the rows in a 28-day window are four, not
// twenty-eight, and the window is widened by a week so the week containing
// `from` is not lost.
func (r *insightsRunner) readIntensityMinutes() map[string]any {
	rows, err := readDayRange(r.db, "intensity_minutes", r.window.from.addDays(-7), r.window.to)
	if err != nil {
		r.warn("reading intensity_minutes: %v", err)
		return map[string]any{"weeks": 0, "moderate_total": nil, "vigorous_total": nil}
	}
	moderate, vigorous := &sampleSet{}, &sampleSet{}
	for _, row := range rows {
		if v, ok := jsonNumberAt(row.data, "moderateValue"); ok {
			moderate.add(v)
		}
		if v, ok := jsonNumberAt(row.data, "vigorousValue"); ok {
			vigorous.add(v)
		}
	}
	block := map[string]any{"weeks": len(rows)}
	if moderate.n() > 0 {
		block["moderate_total"] = moderate.sum()
		block["moderate_weekly_avg"] = moderate.mean()
	} else {
		block["moderate_total"], block["moderate_weekly_avg"] = nil, nil
	}
	if vigorous.n() > 0 {
		block["vigorous_total"] = vigorous.sum()
		block["vigorous_weekly_avg"] = vigorous.mean()
	} else {
		block["vigorous_total"], block["vigorous_weekly_avg"] = nil, nil
	}
	return block
}

// readVO2Max reports the fitness trend from the max_metrics series. Garmin
// stores a running (`generic`) and a cycling block per measured day and skips
// days with no measurement, so this series is sparse by design: `days` is the
// count of days that carry a value, not the window's length.
func (r *insightsRunner) readVO2Max() map[string]any {
	rows, err := readDayRange(r.db, "max_metrics", r.window.from, r.window.to)
	if err != nil {
		r.warn("reading max_metrics: %v", err)
		return map[string]any{"days": 0}
	}
	block := map[string]any{"days": len(rows)}
	for _, sport := range []string{"generic", "cycling"} {
		set := &sampleSet{}
		var first, last *float64
		for _, row := range rows {
			v, ok := jsonNumberAt(row.data, sport, "vo2MaxValue")
			if !ok {
				continue
			}
			set.add(v)
			if first == nil {
				first = round1(v)
			}
			last = round1(v)
		}
		entry := map[string]any{"days": set.n(), "first": first, "last": last, "avg": set.mean()}
		if first != nil && last != nil {
			entry["delta"] = round1(*last - *first)
		} else {
			entry["delta"] = nil
		}
		block[sport] = entry
	}
	return block
}

// readReadiness reports the training-readiness trend. On the reference archive
// this series has zero rows for every day walked, which the `history` walk
// reports as `series_returned_no_rows`; that discrepancy is recorded as an open
// item on the sync stage and is deliberately not worked around here. Zero days
// is reported as zero days.
func (r *insightsRunner) readReadiness() map[string]any {
	rows, err := readDayRange(r.db, "training_readiness", r.window.from, r.window.to)
	if err != nil {
		r.warn("reading training_readiness: %v", err)
		return map[string]any{"days": 0, "score": (&sampleSet{}).summary(), "trend": []rollingPoint{}}
	}
	set := &sampleSet{}
	byDay := map[string]float64{}
	for _, row := range rows {
		v, ok := jsonNumberAt(row.data, "score")
		if !ok {
			continue
		}
		set.add(v)
		byDay[row.day] = v
	}
	if len(rows) == 0 {
		r.warn("no training readiness rows are archived for this window")
	}
	return map[string]any{
		"days":  len(rows),
		"score": set.summary(),
		"trend": rollingAverage(byDay, r.window),
	}
}

// ---------------------------------------------------------------------------
// Human output
//
// The generated commands print a tab-separated table when no machine flag is
// set, so these do too. Every table restates the counts that back its numbers,
// because a recipe that hides its denominator invites a reader to trust an
// average of two nights.
// ---------------------------------------------------------------------------

func printInsightsTable(w io.Writer, recipe string, result map[string]any) error {
	period, _ := result["period"].(map[string]any)
	fmt.Fprintf(w, "%s insights\t%v..%v (%v days)\n", recipe, period["from"], period["to"], period["days"])

	if coverage, ok := result["coverage"].(map[string]any); ok {
		fmt.Fprintln(w, "\nCoverage\tValue")
		fmt.Fprintln(w, "--------\t-----")
		for _, key := range sortedKeys(coverage) {
			fmt.Fprintf(w, "%s\t%s\n", key, formatInsightValue(coverage[key]))
		}
	}

	switch recipe {
	case "sleep":
		printSummaryBlock(w, "Duration (minutes)", result["duration_minutes"])
		printSummaryBlock(w, "Sleep score", result["score"])
		if stages, ok := result["stage_minutes"].(map[string]any); ok {
			fmt.Fprintln(w, "\nStage\tAvg minutes\tShare of measured sleep\tNights")
			fmt.Fprintln(w, "-----\t-----------\t-----------------------\t------")
			for _, stage := range sleepStageFields {
				block, _ := stages[stage.name].(map[string]any)
				if block == nil {
					continue
				}
				fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", stage.name,
					formatInsightValue(block["avg"]), formatInsightValue(block["pct_of_measured"]),
					formatInsightValue(block["n"]))
			}
		}
	case "training":
		if totals, ok := result["totals"].(map[string]any); ok {
			fmt.Fprintln(w, "\nTotal\tValue")
			fmt.Fprintln(w, "-----\t-----")
			for _, key := range sortedKeys(totals) {
				fmt.Fprintf(w, "%s\t%s\n", key, formatInsightValue(totals[key]))
			}
		}
		printRowsBlock(w, "Activity type\tCount\tMinutes\tKm\tAvg HR",
			result["by_type"], []string{"type", "count", "duration_minutes", "distance_km", "avg_hr"})
		printRowsBlock(w, "HR zone\tMinutes\tShare",
			result["hr_zones"], []string{"zone", "minutes", "pct"})
		printRowsBlock(w, "Week starting\tActivities\tMinutes\tKm\tLoad",
			result["weekly"], []string{"week_start", "activities", "duration_minutes", "distance_km", "training_load"})
	}

	if trends, ok := result["trend_vs_prior_period"].(map[string]any); ok {
		fmt.Fprintln(w, "\nTrend vs prior period\tCurrent\tPrior\tDelta")
		fmt.Fprintln(w, "---------------------\t-------\t-----\t-----")
		for _, key := range sortedKeys(trends) {
			block, _ := trends[key].(map[string]any)
			if block == nil {
				continue
			}
			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", key,
				formatInsightValue(block["current"]), formatInsightValue(block["prior"]),
				formatInsightValue(block["delta"]))
		}
	}

	if warnings, ok := result["warnings"].([]string); ok && len(warnings) > 0 {
		fmt.Fprintln(w, "\nNotes")
		fmt.Fprintln(w, "-----")
		for _, warning := range warnings {
			fmt.Fprintf(w, "- %s\n", warning)
		}
	}
	return nil
}

func printSummaryBlock(w io.Writer, title string, v any) {
	block, ok := v.(map[string]any)
	if !ok {
		return
	}
	fmt.Fprintf(w, "\n%s\tValue\n", title)
	fmt.Fprintln(w, strings.Repeat("-", len(title))+"\t-----")
	for _, key := range []string{"n", "avg", "median", "min", "max"} {
		fmt.Fprintf(w, "%s\t%s\n", key, formatInsightValue(block[key]))
	}
}

func printRowsBlock(w io.Writer, header string, v any, fields []string) {
	rows, ok := v.([]map[string]any)
	if !ok || len(rows) == 0 {
		return
	}
	fmt.Fprintf(w, "\n%s\n", header)
	dashes := make([]string, 0, len(fields))
	for range fields {
		dashes = append(dashes, "-----")
	}
	fmt.Fprintln(w, strings.Join(dashes, "\t"))
	for _, row := range rows {
		cells := make([]string, 0, len(fields))
		for _, field := range fields {
			cells = append(cells, formatInsightValue(row[field]))
		}
		fmt.Fprintln(w, strings.Join(cells, "\t"))
	}
}

// formatInsightValue renders a null as an em dash rather than as "0" or
// "<nil>", so a table reader can see the difference between "measured zero"
// and "never measured".
func formatInsightValue(v any) string {
	switch typed := v.(type) {
	case nil:
		return "—"
	case *float64:
		if typed == nil {
			return "—"
		}
		return trimFloat(*typed)
	case float64:
		return trimFloat(typed)
	case string:
		if typed == "" {
			return "—"
		}
		return typed
	default:
		return fmt.Sprint(v)
	}
}

func trimFloat(f float64) string {
	s := fmt.Sprintf("%.1f", f)
	return strings.TrimSuffix(s, ".0")
}

func sortedKeys(m map[string]any) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// weekStart is the Monday on or before this day. Weeks are the unit training
// load is read in, and Monday is the boundary Garmin's own weekly series uses.
func (c civilDay) weekStart() civilDay {
	offset := (int(c.time().Weekday()) + 6) % 7 // Monday = 0
	return c.addDays(-offset)
}

// insightsToday is the window's right-hand edge. It is a variable so a test
// can pin the window over a fixture archive; production always reads the
// caller's own calendar day.
var insightsToday = func() civilDay { return today(time.Now, time.Local) }
